<script lang="ts">
 import {languageOverrides} from "./localization";
 import {uiLabel} from "./english";
 import {onMount} from 'svelte';import {commandIcon} from './desktop-icons';import type {DesktopCommand} from './desktop-menu';import {translator} from './i18n';
 export let language:'ru'|'ro'|"en";export let menus:DesktopCommand[];export let oncommand:(action:string)=>void;
 type Shortcut={id:string;action:string;ru:string;ro:string;x:number;y:number};let entries:Shortcut[]=[],snap=true,context:{x:number;y:number;id?:string}|null=null,area:HTMLDivElement,drag:{id:string;dx:number;dy:number}|null=null;
 $:t=translator(language,$languageOverrides);
 function commands(items:DesktopCommand[]):DesktopCommand[]{return items.flatMap(item=>item.children?commands(item.children):item.action?[item]:[]);}
 function store(){localStorage.setItem('openhau-desktop-shortcuts',JSON.stringify({snap,entries}));}
 function add(command:DesktopCommand,x=20+(entries.length%4)*110,y=20+Math.floor(entries.length/4)*100){if(!command.action||['file:save','overview','manual','updates'].includes(command.action)||entries.some(e=>e.action===command.action))return;entries=[...entries,{id:crypto.randomUUID(),action:command.action,ru:command.ru,ro:command.ro,x,y}];store();}
 onMount(()=>{try{const saved=JSON.parse(localStorage.getItem('openhau-desktop-shortcuts')||'null');if(saved){snap=saved.snap!==false;entries=(saved.entries||[]).filter((row:Shortcut,index:number,all:Shortcut[])=>!['file:save','overview','manual','updates'].includes(row.action)&&all.findIndex(r=>r.action===row.action)===index&&commands(menus).some(c=>c.action===row.action));}}catch{}const create=(e:Event)=>add((e as CustomEvent<DesktopCommand>).detail);window.addEventListener('openhau:desktop-shortcut',create);return()=>window.removeEventListener('openhau:desktop-shortcut',create);});
 function move(e:PointerEvent){if(!drag||!area)return;const rect=area.getBoundingClientRect();let x=Math.max(0,Math.min(rect.width-110,e.clientX-rect.left-drag.dx)),y=Math.max(0,Math.min(rect.height-90,e.clientY-rect.top-drag.dy));if(snap){x=Math.round(x/110)*110;y=Math.round(y/100)*100;}entries=entries.map(s=>s.id===drag!.id?{...s,x:Math.max(0,Math.min(rect.width-110,x)),y:Math.max(0,Math.min(rect.height-90,y))}:s);}
 function end(){if(drag){drag=null;store();}}
 function drop(e:DragEvent){e.preventDefault();const action=e.dataTransfer?.getData('application/x-openhau-command'),command=commands(menus).find(c=>c.action===action);if(command){const r=area.getBoundingClientRect();add(command,Math.max(0,e.clientX-r.left-50),Math.max(0,e.clientY-r.top-40));}}
</script>
<svelte:window onpointermove={move} onpointerup={end} onpointerdown={e=>{if(!(e.target instanceof Element)||!e.target.closest('.desktop-shortcut-menu'))context=null;}}/>
<div bind:this={area} class="desktop-shortcut-area" role="group" aria-label={t('Ярлыки рабочего стола','Comenzi pe desktop')} ondragover={e=>{if(e.dataTransfer?.types.includes('application/x-openhau-command'))e.preventDefault();}} ondrop={drop} oncontextmenu={e=>{e.preventDefault();const r=area.getBoundingClientRect();context={x:Math.min(e.clientX-r.left,r.width-230),y:Math.min(e.clientY-r.top,r.height-220)};}}>
 {#each entries as entry}{@const Icon=commandIcon({id:entry.action.replace(/^.*?:/,''),ru:entry.ru,ro:entry.ro})}<button class="custom-shortcut" style:left={entry.x+'px'} style:top={entry.y+'px'} onpointerdown={e=>{if(e.button!==0)return;const r=e.currentTarget.getBoundingClientRect();drag={id:entry.id,dx:e.clientX-r.left,dy:e.clientY-r.top};e.currentTarget.setPointerCapture(e.pointerId);}} ondblclick={()=>oncommand(entry.action)} onkeydown={e=>{if(e.key==='Enter')oncommand(entry.action);}} oncontextmenu={e=>{e.preventDefault();e.stopPropagation();context={x:entry.x,y:entry.y+50,id:entry.id};}}><Icon size={30}/><span>{uiLabel(entry,language,$languageOverrides)}</span></button>{/each}
 {#if context}<div class="desktop-shortcut-menu" style:left={Math.max(0,context.x)+'px'} style:top={Math.max(0,context.y)+'px'}>{#if context.id}<button onclick={()=>{entries=entries.filter(s=>s.id!==context!.id);store();context=null;}}>{t('Удалить ярлык','Elimină scurtătura')}</button>{/if}<label><input type="checkbox" bind:checked={snap} onchange={store}/>{t('Вид · привязка к сетке','Vizualizare · aliniere la grilă')}</label><button onclick={()=>{context=null;oncommand('file:save');}}>{t('Сохранить базу','Salvează baza')}</button><button onclick={()=>{context=null;oncommand('overview');}}>{t('Обзор','Prezentare')}</button><button onclick={()=>{context=null;oncommand('settings');}}>{t('Параметры','Setări')}</button></div>{/if}
</div>
<style>.desktop-shortcut-area{position:absolute;inset:0 240px 0 0;z-index:0}.custom-shortcut{position:absolute;width:110px;min-height:90px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;padding:10px;background:transparent;color:var(--text);border:0;touch-action:none;user-select:none}.custom-shortcut:hover{background:var(--hover)}.custom-shortcut :global(svg){color:var(--accent)}.custom-shortcut span{font-size:11px;overflow-wrap:anywhere}.desktop-shortcut-menu{position:absolute;z-index:50;background:var(--surface);backdrop-filter:blur(24px);box-shadow:0 8px 24px #0005;width:230px;padding:8px}.desktop-shortcut-menu button,.desktop-shortcut-menu label{display:flex;align-items:center;gap:8px;padding:10px;width:100%;border:0;text-align:left;background:none;color:var(--text)}.desktop-shortcut-menu button:hover{background:var(--hover)}</style>
